EXPERIMENT=complexity3
SCRIPT=k6/tput.js
FROM=1
TO=1

### POLICY 1 ###

FRONTEND_ARGS=$(echo \'-H asdf:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\')
script/bench.sh sm -e "BEELINE_CONFIG=config/beeline/ssm-p1-c1.yaml REPLICAS=3 FRONTEND_ARGS=${FRONTEND_ARGS}" -c docker/ssm-beeline.yaml -n ${EXPERIMENT}-p1-c1 -p beeline -s ${SCRIPT} -f ${FROM} -t ${TO}
